-- Publish four worked teaching pages for each of the 12 Arabic calligraphy stations.
-- Conservative migration: only untouched v1 stage snapshots are updated.
-- No learner attempts, XP, or answer keys are modified.
do $school_guide$
declare changed integer;
begin
 with source as (
  select value as stage from jsonb_array_elements($guide_data$[{"index":0,"lessons":[{"title":"لماذا نبدأ بالسطر؟","body":"تُكتب العربية من اليمين إلى اليسار. قبل رسم أي حرف، تخيّل خطًا أفقيًا يستقر عليه معظم جسم الكلمة. السطر لا يفرض ارتفاعًا متساويًا لكل حرف؛ فالألف واللام ترتفعان فوقه، وقد تهبط أجزاء أخرى تحته. فائدته الأساسية أن تظل الكلمات مرتبة والمسافات منضبطة.","example":"ا  ل  م  — على سطر واحد","note":"ارسم سطرًا خفيفًا ثم قارن مواضع الحروف بالنسبة إليه."},{"title":"النقطة مقياس لا زينة","body":"يستعمل الخطاط في تقاليد الخط الموزون نقطة ناتجة عن سن القلم المقطوط بوصفها وحدة تقريبية للمقارنة بين نسب الحروف. هذه النقطة تختلف عن نقاط تمييز الحروف مثل نقطة الباء. كما أن النسب والقواعد تختلف من خط إلى آخر، فلا تتعامل معها كمقدار ثابت في جميع الأساليب.","example":"نقطة القياس ≠ نقطة الباء","note":"استخدم نقطة سن القلم لمقارنة الأطوال، واترك نقط الحروف في مواقعها الصحيحة."},{"title":"ابدأ بالبطء ثم راجع","body":"عندما تتعلّم شكلًا جديدًا، اتبع حدوده ببطء أولًا واضبط اتجاه الحركة قبل محاولة تسريع اليد. لا يُعد عدد التكرارات وحده دليلًا على التحسن؛ الأفضل أن تقارن وضوح الحروف، واتزان الأقواس، والمسافة بين الكلمات. السطر والقلم والمراجعة أدوات للتعلّم وليس للزخرفة فقط.","example":"ارسم ← اقرأ ← راجع ← أعد","note":"التدرّج في الحركة يمنع تكرار الخطأ بسرعة."},{"title":"مثال محلول: تخطيط كلمة","body":"تخيّل أنك ستكتب كلمة «علم». ابدأ بالسطر، ثم اترك ارتفاعًا واضحًا للام، وحيّزًا لميم لا يغلق فراغها الداخلي. إن ازدحمت الحروف، وسّع المساحة بدل تغيير اتجاه الكتابة. في ورشة الرسم التالية ستطبق هذه الملاحظة قبل أي سؤال.","example":"علم","note":"اسأل نفسك: هل الحروف واضحة؟ هل المسافات متوازنة؟ خطوات التدريب بالترتيب: جهّز الورقة ← حدّد السطر ← ارسم ببطء ← راجع النِّسب."}]},{"index":1,"lessons":[{"title":"الحرف نفسه بأشكال سياقية","body":"الحرف العربي قد يبدو منفردًا أو أوليًا أو وسطيًا أو نهائيًا تبعًا لموقعه ووصلاته. مثلًا الباء: ب، بـ، ـبـ، ـب. جميعها حرف واحد، وليست أربعة أصوات مختلفة. احتفظ بالهيكل العام وتعلّم كيف يتغير طرف الوصل في كل موضع.","example":"ب  |  بـ  |  ـبـ  |  ـب","note":"قارن شكل الباء المنفرد بالباء في بداية «بيت»."},{"title":"ستة حروف توقف الوصل بعدها","body":"احفظ المجموعة التالية: ا، د، ذ، ر، ز، و. هذه الحروف لا تتصل بالحرف الذي يأتي بعدها، وإن أمكنها الاتصال بما قبلها. لذلك تظهر داخل بعض الكلمات فجوة وصل صغيرة، لكنها لا تعني بدء كلمة جديدة ولا تستلزم مسافة بين كلمتين.","example":"ا  د  ذ  ر  ز  و","note":"التوقف بعد الدال أو الواو طبيعي في العربية، وليس خطأً في الخط."},{"title":"الوصل في كلمة حقيقية","body":"في «بيت» يتصل الباء بالياء ثم بالتاء؛ أما في «ورد» فالواو لا يصل الراء، والراء لا يصل الدال. لاحظ أن الكلمات تبقى كلمة واحدة رغم انقطاع بعض الوصلات. ومن المفيد مقارنة «ب، ت، ث»: تتشابه هياكل كثيرة لها، وتُميزها النقط.","example":"بيت  /  ورد  /  ب ت ث","note":"الباء نقطة واحدة أسفل؛ التاء نقطتان فوق؛ الثاء ثلاث نقط فوق."},{"title":"مثال محلول: بناء حرف الباء","body":"إذا طُلب ترتيب أشكال الباء بحسب موقعها فابدأ بالمنفرد ب، ثم الأولي بـ، ثم الوسطي ـبـ، وأخيرًا النهائي ـب. انتبه إلى أن شكل الاتصال يتبع الحروف المجاورة. جرّب رسم الحالات الأربع على خط واحد قبل الانتقال إلى الأسئلة.","example":"ب ← بـ ← ـبـ ← ـب","note":"قِس اختلاف مواضع الوصل ولا تغيّر هوية الحرف."}]},{"index":2,"lessons":[{"title":"لماذا ندرس النسخ؟","body":"خط النسخ من أكثر خطوط العربية ملاءمة للنصوص المتصلة المقروءة، وتستند إليه أشكال طباعية عديدة. الهدف الأول فيه وضوح الحروف وتوازنها، لا سرعة اليد أو ازدحام الزخرفة. ضع الحروف على خط أساس منتظم واترك فراغًا يسمح بتمييز الأقواس والأجزاء الداخلية.","example":"بيت  —  نبت","note":"اقرأ الكلمة بعينيك بعد كتابتها: هل تُرى كل نقطة بوضوح؟"},{"title":"النقاط تصنع الفارق","body":"تشترك الباء والتاء والثاء في هيئة أساسية لكثير من مواضع الكلمة، لكن الباء لها نقطة تحت، والتاء نقطتان فوق، والثاء ثلاث فوق. للنون نقطة واحدة فوق. حتى لو تشابه جسم الحرف، فإن حذف النقط أو تقاربها الزائد قد يغيّر القراءة. ضع النقط بعد رسم الهيكل وراجعها.","example":"ب = • تحت | ت = •• فوق | ث = ••• فوق | ن = • فوق","note":"العدد والموقع يساعدان في التمييز، لا لون النقطة أو حجم الورق."},{"title":"اترك مساحة للقوس","body":"تظهر في النسخ أقواس وفراغات داخلية ينبغي ألا تنغلق تحت ضغط الوصلات. إذا ازدحمت حروف «نبت» أو «بيت»، وسّع التكوين قليلًا؛ لا تحذف الوصلات ولا تغير اتجاه العربية. الهدف حروف يستطيع القارئ تمييزها بسرعة.","example":"بَيْت  /  نَبْت","note":"وضوح القوس والفراغ الداخلي أهم من إضافة الزينة."},{"title":"مثال محلول: كلمة «بيت»","body":"ارسم سطرًا، ثم هيكل الباء فالياء فالتاء بوصلاتها، ثم أضف النقط: نقطة تحت الباء، ونقطتان تحت الياء، ونقطتان فوق التاء. افحص مدى انتظام الكلمة وحجم الفراغات. هذه مراجعة ذاتية للنسخ وليست حكمًا آليًا على جمال خطك.","example":"خط أساس ← حروف ← نقط ← مراجعة","note":"لا تبدأ بالتزيين قبل التأكد من صحة الكلمة. خطوات التدريب بالترتيب: ارسم السطر ← اكتب الحروف ← أضف النقط ← راجع التوازن."}]},{"index":3,"lessons":[{"title":"الكلمة ليست حروفًا منفصلة","body":"في خط النسخ، اتصال الحروف وتناسب ارتفاعاتها يجعلان الكلمة وحدة متوازنة. الحروف الصاعدة مثل الألف واللام تحتاج مساحة رأسية واضحة، بينما بعض الأقواس والفراغات تحتاج مساحة أفقية. لا تُساوِ بين جميع الأجزاء قسرًا ولا تفصل الحروف القابلة للوصل.","example":"سلام  /  العلم","note":"راقب ارتفاع اللام والألف بالنسبة إلى جسم الميم."},{"title":"اللام والألف في كلمة","body":"عندما تتصل اللام بالألف يظهر تركيب معروف هو «لا». لا يُعد هذا تركيبًا من حرف واحد؛ إنه صورتان متصلتان وفق قواعد الخط. في «سلام» لاحظ الاتصال بين السين واللام والألف ثم شكل الميم في النهاية.","example":"لا  —  سلام","note":"إتقان اتصال اللام بالألف ضروري قبل تركيب الجمل الطويلة."},{"title":"من كلمة إلى جملة حقيقية","body":"اكتب «العلم نور». العبارة مكتملة المعنى، وتتكون من كلمتين تفصل بينهما مساحة أكبر من الفراغات داخل الكلمة. اختر طول السطر المناسب ولا تضغط آخر كلمة كي لا تختفي تفاصيل حروفها. يمكن إضافة التشكيل عند الحاجة، لكنه لا يحل محل جودة بنية الحرف.","example":"العلم نور","note":"السطر المنتظم والمسافات المقروءة هما الأساس في الجمل."},{"title":"مثال محلول: جملة من ثلاث كلمات","body":"للتدريب على ترتيب الكلمات في سياق مفيد، اقرأ «العلم نور للإنسان». اكتب أولًا «العلم»، ثم اترك فراغ كلمة مناسبًا قبل «نور»، ثم «للإنسان». اقرأ الجملة بعد رسمها وتحقق من اتصال الحروف والنقط وصحة الإملاء.","example":"العلم ← نور ← للإنسان","note":"الكتابة الجيدة تبدأ من صحة العبارة وتنتقل إلى جمالها."}]},{"index":4,"lessons":[{"title":"ما وظيفة الرقعة؟","body":"الرقعة خط عملي شائع للكتابة اليدوية اليومية. يغلب على كثير من نماذجه اقتصاد الحركة وصِغر بعض الأشكال قياسًا بالنسخ، لكنه ليس كتابة عشوائية ولا نسخة مشوهة من النسخ. يُستخدم للسرعة المنظمة التي تبقى فيها الكلمات مقروءة.","example":"قلم  —  عمل","note":"عند التدريب ابدأ ببطء، ثم زد الإيقاع تدريجيًا."},{"title":"الاختصار لا يلغي الحروف","body":"الرقعة تختصر بعض الحركات وتصل الحروف بكفاءة؛ لكنها لا تسمح بإلغاء النقط أو محو الفرق بين حرفين. إذا اختلطت الباء بالتاء، أو اختفت نقطة القاف أثناء السرعة، فتوقف وأعد الرسم ببطء. المعيار ليس عدد الكلمات في الدقيقة وحده.","example":"خط واضح → حركة اقتصادية → سرعة","note":"لا تجعل سرعة اليد أعلى من قدرتك على قراءة ما كتبت."},{"title":"قارن السرعة بالوضوح","body":"اكتب «قلم» مرة ببطء وأخرى بسرعة متوسطة، ثم قارن شكل القاف واللام والميم ومواقع النقط. إن بقيت الكلمة مقروءة وانتظمت على السطر، فقد حافظت على هدف الرقعة العملي. إن تقلصت الكلمة حتى فقدت هويتها، أبطئ من جديد.","example":"قلم  /  كتاب  /  عمل","note":"الكلمات القصيرة المألوفة أفضل بداية من التراكيب الطويلة."},{"title":"مثال محلول: خطة الرقعة","body":"ابدأ بخط واضح وبطيء، راجع الحروف والنقط، ثم زد السرعة قليلًا وتحقق من القراءة مرة أخرى. لا تبدأ بالديواني المتشابك أو زخارف الثلث إذا كانت حروف الرقعة الأساسية غير واضحة. كرر على كلمة «كتاب» بمقارنة نسختين.","example":"اكتب ببطء ← اضبط الحروف ← زد السرعة ← تحقق من الوضوح","note":"هذه هي دورة التدريب الصحيحة قبل الاختبار."}]},{"index":5,"lessons":[{"title":"السرعة تحتاج إيقاع الجملة","body":"إتقان الرقعة لا يتوقف على حرف أو كلمة؛ بل يحتاج إلى إيقاع منتظم عبر جملة كاملة. العبارة «الوقت ثمين» تسمح بفحص المسافة بين كلمتين. أما «العمل أساس النجاح» فتختبر ترتيب ثلاث كلمات ووضوح الحروف الصاعدة والفراغات في نهاية السطر.","example":"الوقت ثمين","note":"اكتب الجملة على سطر واحد أولًا ثم جرّب زيادة السرعة."},{"title":"كيف نحافظ على حدود الكلمات؟","body":"عند الكتابة السريعة يجب ألا تتداخل نهاية الكلمة مع بداية التالية. اترك فراغًا بين الكلمات أكبر من المسافة داخل الوصلات. راقب بداية الجملة ونهايتها معًا: فقد تُكتب الكلمة الأولى بعناية ثم تُضغط الأخيرة إن استعجلت.","example":"العمل | أساس | النجاح","note":"وجود فراغ واضح يساعد القارئ على فهم الجملة دون تخمين."},{"title":"ثلاث محاولات لا محاولة واحدة","body":"للتدرّب قارن ثلاث نسخ: الأولى بطيئة دقيقة، والثانية بسرعة متوسطة، والثالثة أسرع قليلًا. سجّل ملاحظات عن قابلية القراءة، والنقط، وانتظام المسافة. إذا أصبحت النسخة الثالثة أصعب قراءة، فارجع إلى السرعة الثانية وراجع موضع الخطأ.","example":"الدقة ← سرعة متوسطة ← سرعة مضبوطة","note":"المقياس هو الوضوح مع الإيقاع، وليس عدد الحروف فقط."},{"title":"مثال محلول: ترتيب العبارة","body":"اقرأ العبارة «العمل أساس النجاح». اكتبها بهذا الترتيب: «العمل»، ثم «أساس»، ثم «النجاح». عند سؤال الإكمال تذكّر الجملة الأخرى التي تدربت عليها: «الوقت ثمين». لا تُحوّل التمرين إلى سلاسل حروف بلا معنى.","example":"العمل ← أساس ← النجاح","note":"جمل حقيقية تساعد على تدريب الحروف والذاكرة معًا."}]},{"index":6,"lessons":[{"title":"الكوفي ليس نمطًا واحدًا","body":"كلمة «كوفي» تُطلق على عائلة واسعة من أساليب الكتابة العربية التاريخية. بعض أنواعها زاوٍ وهندسي، وبعضها أكثر مرونة في الخطوط والأقواس؛ لذلك لا يصح القول إن كل كوفي مربع. تظهر تقاليد كوفية في نقوش ومخطوطات وزخارف معمارية متنوعة.","example":"كوفي تاريخي ≠ كوفي مربع دائمًا","note":"المحطة تستخدم شبكة هندسية للتعلّم، وليس لوصف كل الأساليب التاريخية."},{"title":"لماذا تُستعمل الشبكة؟","body":"في تمرين الكوفي الهندسي تساعد شبكة مربعات بسيطة على ضبط الأطوال ومحاذاة الأجزاء. ليست هذه الشبكة قانونًا تاريخيًا عامًا لكل الحروف الكوفية، لكنها وسيلة عملية لتعليم النسب. اترك مساحات بيضاء حول الأجزاء المرسومة حتى يبقى التكوين متوازنًا.","example":"شبكة ← توزيع الحروف ← فراغات","note":"المساحة البيضاء جزء من التصميم مثل الأجزاء المرسومة."},{"title":"الزخرفة تأتي بعد القراءة","body":"إذا أردت أن تصمّم كلمة «نور» بشكل هندسي، اكتبها أولًا كتابة واضحة. بعد ذلك انقل الهيكل إلى شبكة، واضبط الزوايا ثم أعد النظر في النقط والوصلات. إن اختفت الكلمة تحت الزخرفة، فأنت بحاجة إلى تقليل عناصر التصميم.","example":"نور","note":"اقرأ الكلمة قبل الزخرفة وبعدها لتتحقق من وضوحها."},{"title":"مثال محلول: خطوات التصميم","body":"اختر كلمة قصيرة مثل «نور»، ثم حدّد شبكة مناسبة، ووزّع الحروف، وأخيرًا راجع الوضوح. لا تبدأ بحشو الفراغات بزينة عشوائية؛ لأن كثافة الزخارف يمكن أن تشتّت القارئ. استخدم الشبكة لرؤية التناسب لا لتعقيد الكلمة.","example":"اختر الكلمة ← حدّد الشبكة ← وزّع الحروف ← راجع الوضوح","note":"ما تتعلمه هنا أساس للكوفي الهندسي التعليمي."}]},{"index":7,"lessons":[{"title":"الثلث خط للعرض المتقن","body":"للثلث حضور بارز في كثير من العناوين والزخارف المعمارية. يُظهر غالبًا حروفًا طويلة وامتدادات منحنية وتركيبًا متأنّيًا. ليس تكبيرًا ميكانيكيًا لخط النسخ؛ إذ تختلف قواعد الحركة والنسب وترتيب الحروف. لذلك ندرسه كتكوين بصري يسبق تجميله تخطيط واضح.","example":"العلم","note":"اختر كلمة قصيرة وافحص موضع الألف واللام قبل الزخرفة."},{"title":"الامتدادات والفراغات","body":"في الثلث قد تشغل السيقان والامتدادات مساحات مرتفعة، بينما تلتف أقواس الحروف في أسفل التكوين. عليك أن توازن بين هذه الكتل والفراغات البيضاء. لا تجعل الألف الطويلة تطغى على بقية الكلمة ولا تزاحم النقط حتى تصبح القراءة صعبة.","example":"ساق صاعد + قوس منحني + فراغ","note":"كل امتداد له وظيفة جمالية وبنائية، وليس إضافة بلا ضابط."},{"title":"التكوين ثم الزينة","body":"ابدأ برسم مخطط للكلمة، وحدّد مواقع الحروف الصاعدة، ثم ارسم امتدادات محتملة، وبعدها اختبر الفراغات والقراءة. لا تلجأ إلى التشابك أو التظليل قبل أن يكون النص صحيحًا. إتقان الثلث يتطلب وقتًا في حركة القلم والنِّسب.","example":"مخطط → امتدادات → فراغات → قراءة","note":"التدرّج يمنع أن تغطي الزينة مواضع الحروف اللازمة."},{"title":"مثال محلول: كلمة «العلم»","body":"في كلمة «العلم» جرّب وضع الألف واللام بارتفاعات موزونة فوق القوس الأقرب إلى الميم. اقرأ الكلمة كاملة بعد كل تعديل. عند ترتيب خطوات تكوين زخرفي، تذكّر أن تخطيط الحروف يسبق امتداداتها، ثم تأتي موازنة الفراغات والمراجعة.","example":"ارسم مخططًا ← حدّد الامتدادات ← وازن الفراغات ← راجع القراءة","note":"ليس مطلوبًا منك إتقان الثلث الاحترافي في هذه المحطة التمهيدية."}]},{"index":8,"lessons":[{"title":"أصل الديواني ووظيفته","body":"تطوّر الخط الديواني في البيئة العثمانية وكان مرتبطًا بالمراسلات والدواوين الرسمية. لذلك لا يُعد نمط الملاحظات المدرسية السريعة الشائع؛ فهذا الدور أقرب إلى الرقعة. تعلّم جذوره يساعدك في فهم سبب ميله إلى التكوينات المتدفقة والمترابطة.","example":"الديواني: دواوين ومراسلات","note":"الاسم نفسه يذكّر بوظيفته التاريخية."},{"title":"الانسياب مع الحفاظ على القراءة","body":"تظهر في نماذج ديوانية كثيرة انحناءات متدفقة وتقارب بين الحروف، وقد تتداخل عناصر الكلمة في الأساليب الزخرفية. لكن التداخل الكثير قبل فهم الأشكال يُصعّب القراءة. ابدأ بكلمة قصيرة «سلام»، وابقِ النقط والأطراف واضحة، ثم جرّب تقاربًا معتدلًا.","example":"سلام","note":"التقارب ليس إذنًا لإخفاء الحروف أو حذف الوصلات الصحيحة."},{"title":"الفراغ يوازن الكثافة","body":"حتى في اللوحة الديوانية المتقاربة، يبقى الفراغ مهمًا. إن امتلأ تكوينك حتى تعذر فصل الحروف، خفّف التداخل. الاستدارة والتدفق يخدمان الإيقاع البصري، أما وضوح البنية فيضمن فهم العبارة. لا تُبدّل هذا الخط بالرقعة إذا كان هدفك تكوينًا زخرفيًا.","example":"تقارب محسوب + فراغ واضح","note":"كثافة الخط تحتاج مساحات للتنفس."},{"title":"مثال محلول: بناء «سلام»","body":"اكتب «سلام» بوضوح على السطر، ثم راجع الحروف والنقط، وقرّب بعض الوصلات، وفي النهاية وازن الفراغات. إذا لم تعد تقرأ الكلمة بسهولة فأعد خطوة إلى الوراء. هذا التمرين في الانسياب يسبق المحاكاة الأصعب للديواني الجلي.","example":"اكتب الكلمة ← راجع الحروف ← قرّب الوصلات ← وازن الفراغات","note":"خطوات تدريجية أفضل من زخرفة معقدة منذ البداية."}]},{"index":9,"lessons":[{"title":"ما النستعليق؟","body":"النستعليق أحد أبرز تقاليد الخط الفارسي، وقد اشتهر في إيران وأجزاء من شبه القارة الهندية. يُعرف بين كثير من المتعلمين باسم الخط الفارسي. له إيقاع خاص في وصل الحروف وتدرّج الكلمات، ولا يُمكن الحصول عليه بإمالة خط النسخ عشوائيًا.","example":"نستعليق = تقليد خطي مستقل","note":"اسم النستعليق هو المصطلح الذي ستحتاج إلى تذكره."},{"title":"الميل والأقواس المعلّقة","body":"قد تتدرج الكلمات في النستعليق على محور مائل وتبدو بعض الأقواس كأنها معلّقة أسفل اتجاه الكلمة. انتبه إلى حركة الوصلات وتوازن المنحنيات بالنسبة إلى المحور. المهم أن يشكل الميل نظامًا متناسقًا، لا أن تصبح كل حروف الكلمة مائلة بزاوية عشوائية.","example":"محور مائل + قوس معلّق","note":"حافظ على اتصال الحروف العربية ووضوح النقاط."},{"title":"المقارنة بين «جمال» و«حياة»","body":"اكتب «جمال» على سطر عادي، ثم على محور خفيف الميل وقارن حركة الجيم والألف واللام. جرّب «حياة» بالطريقة ذاتها. إذا بدا الميل مفصولًا عن الأقواس، أعد ترتيب الهيكل. التدريب البسيط يساعد على رؤية الفكرة دون ادعاء إتقان النستعليق التاريخي.","example":"جمال  —  حياة","note":"نقارن التوازن بين محور الكلمة وأقواسها، لا درجة الميل وحدها."},{"title":"مثال محلول: خطة التدريب","body":"حدّد محور الكلمة، ثم ارسم الهيكل، ووازن الأقواس والانحناءات، وفي النهاية تحقق من القراءة. لا تنس أن النستعليق تطوّر في سياقات فارسية وجنوب آسيوية، وله نسب ومدارس متنوعة. الترتيب الصحيح للعمل يبدأ بالمحور وينتهي بمراجعة النص.","example":"حدّد المحور ← ارسم الهيكل ← وازن الأقواس ← تحقق من القراءة","note":"تدرّج من الهيكل إلى التفاصيل قبل التزيين."}]},{"index":10,"lessons":[{"title":"تقاليد الغرب الإسلامي","body":"الخط المغربي اسم لأساليب كتابة تطورت في المغرب والأندلس والغرب الإسلامي. تظهر في مخطوطات تاريخية منه أقواس مستديرة وهياكل تختلف عن بعض الأشكال المشرقية. ليس نموذجًا واحدًا ثابتًا، كما أن طبعات العصر الحديث قد لا تتبع جميع التفاصيل القديمة.","example":"مغرب  /  فقه","note":"ابدأ بملاحظة الأسلوب العام قبل مقارنة الحروف المنفردة."},{"title":"تنقيط الفاء والقاف تاريخيًا","body":"في بعض التقاليد المغربية التاريخية تقع نقطة الفاء أسفل جسمها، بينما تُكتب القاف بنقطة واحدة فوقها. أما الكتابة المشرقية الشائعة فتجعل للفاء نقطة فوق وللقاف نقطتين فوق. هذه المقارنة تخص نماذج تاريخية بعينها ولا تعممها على كل ما يطبع في المغرب اليوم.","example":"فاء مغربية تاريخية: نقطة أسفل | قاف: نقطة واحدة فوق","note":"لا تستنتج الحرف من نقطة منفردة دون سياق الكلمة والمخطوطة."},{"title":"كيف تقرأ مخطوطة مختلفة؟","body":"لاحظ شكل الحرف أولًا، ثم افحص مواضع النقاط، واقرأ الكلمة في سياقها، وقارن بنظائرها في المخطوطة نفسها. فقد يظن القارئ المعتاد على التنقيط المشرقي أن حرفًا مغربيًا غير مألوف، بينما المشكلة في اختلاف الاصطلاح لا في خطأ الكتابة.","example":"الشكل ← النقط ← السياق ← المقارنة","note":"القراءة التاريخية تعتمد على سياق الكلمة وعلى نظام المخطوطة."},{"title":"مثال محلول: كلمة «فقه»","body":"عند رؤية «فقه» في نموذج مغربي تاريخي، انتبه إلى أن الفاء قد تظهر بنقطة تحت، والقاف بنقطة واحدة فوق. تحقّق من الكلمة كاملة قبل الحكم على كل حرف. اكتبها في ورشة التدريب، ثم أضف ملاحظة تشرح اختلاف النقط بين بعض المخطوطات التاريخية والكتابة المتداولة.","example":"فـ قـ هـ  ←  فقه","note":"المهم هنا الفهم والتمييز وليس تقليد كل تفاصيل الخط المغربي. خطوات التدريب بالترتيب: لاحظ شكل الحرف ← افحص النقط ← اقرأ السياق ← قارن بنظائره."}]},{"index":11,"lessons":[{"title":"كيف تختار الخط المناسب؟","body":"ابدأ بسؤالين: لمن تكتب؟ وما وظيفة النص؟ إذا كان نصًا طويلًا يُراد له وضوح مستمر، فالنسخ اختيار ملائم. إذا كانت ملاحظات يومية سريعة، فالرقعة عملي. وإذا أردت عنوانًا أو لوحة زخرفية، فقد تختار الثلث أو أحد أساليب الكوفي وفق مستوى خبرتك.","example":"النص المقروء: نسخ | اليومي: رقعة | العرض: ثلث أو كوفي","note":"لا تختَر أكثر الخطوط تعقيدًا لمجرد أنها تبدو مزخرفة."},{"title":"من العبارة إلى مخطط اللوحة","body":"المشروع الختامي عبارة عربية حقيقية: «اليمن أرض الحضارة والتاريخ». حدّد مساحة للكتابة، ثم وزّع الكلمات مع فراغات واضحة. اكتب العبارة صحيحة إملائيًا في مسودة أولى، ثم اختر خطًا مناسبًا وأعد تخطيطها. لا تُضاف الزخرفة قبل ضبط النص.","example":"اليمن أرض الحضارة والتاريخ","note":"اقرأ العبارة كاملة: لا تنس كلمة «التاريخ» في نهايتها."},{"title":"التوازن بين القراءة والزينة","body":"افحص اللام والألف والحروف الهابطة، ثم راجع النقط واتصال الحروف ومسافات الكلمات. قد يبدو التكوين جميلًا من بعيد، لكنه ضعيف إذا صعبت قراءته. لذلك جرّب نسخة أولى بسيطة ثم نسخة ثانية زخرفية محسّنة؛ وقارن بينهما بدل الاكتفاء بمحاولة واحدة.","example":"نسخة واضحة → مراجعة → نسخة مزخرفة","note":"لا يُقيّم الرسم هنا بالذكاء الاصطناعي، بل تُراجع خصائصه بنفسك."},{"title":"مثال محلول: خطة المشروع","body":"اختر العبارة أولًا، ثم حدّد الخط وفق الغرض، واكتب مسودة على سطر إرشادي، وراجع وضوح اللوحة وتهجئة الكلمات. أسئلة المحطة تقيس فهم الاختيار والتخطيط والتمييز بين الخطوط. أما ورشة الرسم فهي تطبيق فني حر لا تُحوّل درجته إلى اختبار آلي مزعوم.","example":"اختر العبارة ← حدّد الخط ← اكتب مسودة ← راجع اللوحة","note":"بعد الاختبار يمكنك إعادة كتابة اللوحة وتحسينها مرة أخرى."}]}]$guide_data$::jsonb)
 ), applied as (
  update public.school_editor_stages s
  set draft=jsonb_set(s.draft,'{lessons}',source.stage->'lessons',true),
      published=jsonb_set(s.published,'{lessons}',source.stage->'lessons',true),
      version=s.version+1,
      published_version=s.published_version+1,
      updated_at=now()
  from source
  where s.course_slug='arabic-calligraphy'
    and s.stage_index=(source.stage->>'index')::integer
    and s.version=1 and s.published_version=1
    and s.draft=s.published
    and not (s.published ? 'lessons')
  returning s.stage_index
 )
 select count(*) into changed from applied;
 if changed<>12 then
  raise exception 'Expected 12 untouched calligraphy stages; applied to %',changed;
 end if;
end
$school_guide$;
